const s=ctx.state,gl=ctx.gl;
s.program=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,"#version 300 es
precision highp float;
#define GLSLIFY 1
in vec2 v_uv;out vec4 outColor;uniform vec2 u_resolution;uniform sampler2D u_image;
uniform float u_shine;
uniform float u_light;
float blinnPhongSpecular(
  vec3 lightDirection,
  vec3 viewDirection,
  vec3 surfaceNormal,
  float shininess) {

  //Calculate Blinn-Phong power
  vec3 H = normalize(viewDirection + lightDirection);
  return pow(max(0.0, dot(surfaceNormal, H)), shininess);
}

void main(){vec2 uv=v_uv,p=(uv*2.-1.)*u_resolution/min(u_resolution.x,u_resolution.y);vec3 color;float r=length(p);color=vec3(.035,.075,.13);if(r<.8){vec3 n=normalize(vec3(p,sqrt(.64-dot(p,p)))),l=normalize(vec3(sin(u_light),.6,cos(u_light)));float spec=blinnPhongSpecular(l,vec3(0,0,1),n,u_shine);color=vec3(.18,.55,.65)*(.15+.65*max(dot(n,l),0.))+vec3(1,.9,.75)*spec;}
outColor=vec4(color,1);}");
